#!/usr/bin/bash

echo "::group:: ===$(basename "$0")==="

set -eoux pipefail

# Put the Amethystora artwork where the boot menu, the boot splash, GDM and the Logo Menu look for it.
# The artwork itself lives in system_files/shared and is generated by branding/generate.mjs.

# Boot menu: GRUB reads its own bitmap font format, so the Inter that theme.txt asks for is built
# here from the TTF the image already ships for the boot splash. GRUB looks the font up by the name
# stored in the file, which grub2-mkfont always writes as "<family> <style> <size>" — for a regular
# face, "<family> Regular 16". The family is given here instead of being taken from the TTF, whose
# own family name is "Inter 18pt" in some Inter releases and would stop matching theme.txt.
GRUB_THEME_DIR=/usr/share/grub/themes/amethystora
GRUB_FONT_NAME="Inter Regular 16"
grub2-mkfont --size=16 --name="Inter" \
    --output="${GRUB_THEME_DIR}/font16.pf2" /usr/share/fonts/rsms-inter-fonts/Inter-Regular.ttf
test -s "${GRUB_THEME_DIR}/font16.pf2"
# The name in the font file and the name theme.txt asks for have to be the same string, or the menu
# silently falls back to GRUB's own font
grep -aq "${GRUB_FONT_NAME}" "${GRUB_THEME_DIR}/font16.pf2"
grep -qE "^[[:space:]]*item_font = \"${GRUB_FONT_NAME}\"$" "${GRUB_THEME_DIR}/theme.txt"

# Boot splash: the Amethystora theme runs on the script plugin (amethystora.script and its images, from
# branding/generate.mjs). Its Font= lines are not read by the plugin but make dracut put Inter in the initramfs.
# 19-initramfs.sh bakes the selected theme into the initramfs.
plymouth-set-default-theme amethystora

# Logos under Fedora's own file names, which build.sh takes away with fedora-logos. The names cannot
# be changed: they are where GDM, the Settings About page (gnome-control-center is built with the path
# baked in) and Fedora's fallback boot splash look. The Amethystora pictures are installed there.
declare -A UPSTREAM_ARTWORK=(
    # The login screen, which draws on a dark background: the wordmark with the dark lettering
    # disappears into it and leaves the gem on its own. The lit variant, matching the stone the boot
    # splash hands over still glowing. zz1-amethystora-modifications names the same file directly as
    # well, so the greeter is right whichever of the two GDM reads.
    [/usr/share/pixmaps/fedora-gdm-logo.png]=/usr/share/pixmaps/amethystora-wordmark-glow.png
    [/usr/share/pixmaps/fedora-logo-small.png]=/usr/share/pixmaps/amethystora-wordmark-small.png
    [/usr/share/pixmaps/fedora-logo.png]=/usr/share/pixmaps/amethystora-wordmark.png
    [/usr/share/pixmaps/fedora_logo_med.png]=/usr/share/pixmaps/amethystora-wordmark-medium.png
    [/usr/share/pixmaps/fedora_whitelogo_med.png]=/usr/share/pixmaps/amethystora-wordmark-white.png
    # Settings -> About draws fedora-logo-icon.png, the path Fedora compiles into gnome-control-center
    [/usr/share/pixmaps/fedora-logo-icon.png]=/usr/share/pixmaps/amethystora-logo-512.png
    [/usr/share/pixmaps/fedora-logo-sprite.png]=/usr/share/pixmaps/amethystora-logo-400.png
    [/usr/share/pixmaps/system-logo-white.png]=/usr/share/pixmaps/amethystora-logo-white.png
    [/usr/share/icons/hicolor/scalable/places/fedora-logo-sprite.svg]=/usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg
    [/usr/share/icons/hicolor/scalable/places/fedora_white_logo.svg]=/usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg
    [/usr/share/icons/hicolor/scalable/places/fedora_whitelogo.svg]=/usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg
    # Fedora's spinner theme is the fallback splash; its watermark.png is an Amethystora file already
    [/usr/share/plymouth/themes/spinner/silverblue-watermark.png]=/usr/share/plymouth/themes/spinner/watermark.png
)

for target in "${!UPSTREAM_ARTWORK[@]}"; do
    artwork="${UPSTREAM_ARTWORK[${target}]}"
    test -s "${artwork}"
    install -Dpm0644 "${artwork}" "${target}"
done

# Top bar: the Logo Menu draws the Amethystora gem in its own colours, not a symbolic silhouette
# that GNOME would repaint in the panel's foreground white. 04-amethystora-logomenu-extension and
# zz0-amethystora-modifications turn the symbolic icon off and pick index 29, entry 30 of the
# coloured list. That entry and entry 31 of the symbolic list are the extension's Universal Blue
# logo, and both are replaced with Amethystora artwork below, under the extension's file names that
# 07-debrand.sh then renames. Selecting the entries by number is what makes the checks necessary: a
# reordered list would silently put somebody else's logo in the panel.
LOGOMENU=/usr/share/gnome-shell/extensions/logomenu@aryan_k
logomenu_entries() {
    sed -n "/$1/,/^\];/p" "${LOGOMENU}/constants.js" | grep -oE "/Resources/[^']+"
}
# menu-button-icon-image indexes the arrays from 0, and the symbolic array opens with a plain icon
# name carrying no /Resources/ path: index 30 is the 30th path listed there, index 29 the 30th here.
[[ "$(logomenu_entries SymbolicDistroIcons | sed -n '30p')" == "/Resources/ublue-logo-symbolic.svg" ]]
install -Dpm0644 /usr/share/icons/hicolor/scalable/actions/amethystora-logo-symbolic.svg \
    "${LOGOMENU}/Resources/ublue-logo-symbolic.svg"
[[ "$(logomenu_entries ColouredDistroIcons | sed -n '30p')" == "/Resources/ublue-logo.svg" ]]
install -Dpm0644 /usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg \
    "${LOGOMENU}/Resources/ublue-logo.svg"

echo "::endgroup::"
